window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6f81e1b0fd2139ab"]={"versions": [{"id": "FIG-6f81e1b0fd2139ab", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (Activity Diagram).\n</li><li><strong>Architektur-Kontext &amp; Zweck:</strong>\n<ul class=\"fig-list\"><li>Spezifikationskontext: AUTOSAR Foundation E2E Protocol Specification ([PRS_E2E_01191], bezogen auf [RS_E2E_08539], Releases R22-11 / R23-11).\n</li><li>Funktionaler Bereich: E2E-Methodenprofile (<code>PXXm</code>, z. B. P04m, P07m, P22m) zur E2E-Absicherung serviceorientierter Client/Server- und Request/Response-Kommunikation (z. B. via SOME/IP über den E2E Transformer bzw. ara::com / RTE).\n</li><li>Zweck: Normative Definition des atomaren Dekodierungsschritts <em>„Read Message Type“</em> innerhalb der Empfänger-Prüfroutinen <code>E2E_PXXmSourceCheck()</code> (Client-seitig zur Response-Prüfung) und <code>E2E_PXXmSinkCheck()</code> (Server-seitig zur Request-Prüfung).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontexte:</strong>\n<ul class=\"fig-list\"><li><code>E2E_PXXmSourceCheck()</code>: Prüfroutine der Quelle (Client/Caller-Perspektive).\n</li><li><code>E2E_PXXmSinkCheck()</code>: Prüfroutine der Senke (Server/Callee-Perspektive).\n</li><li>Platzhalter <code>XX</code>: Kennzeichnet das konkrete Basisprofil (z. B. 04, 07); <code>m</code> kennzeichnet die Methoden-Profilvariante.\n</li></ul>\n</li><li><strong>Eingangsdaten &amp; Variablen:</strong>\n<ul class=\"fig-list\"><li><code>Data</code>: Bytestring-Puffer (<code>const uint8*</code>) der empfangenen serialisierten PDU/Payload.\n</li><li><code>ReceivedMessageType</code>: Lokale Variable (Typ <code>uint8</code> bzw. profil-spezifisches Enum) zur Speicherung des normalisierten 2-Bit-Nachrichtentyps.\n</li><li><code>Offset</code>: Konfigurierter Basis-Offset (in Byte/Bit je nach Profilspezifikation) des E2E-Headers innerhalb der PDU.\n</li><li><code>PXXMMESSAGE_POS</code>: Profilspezifische Konstante für die relative Position des Message-Type-Felds.\n</li></ul>\n</li><li><strong>UML-Notationselemente:</strong>\n<ul class=\"fig-list\"><li><em>Initial Node</em> (Startknoten, gefüllter schwarzer Kreis).\n</li><li><em>Opaque Action</em> (Aktionszustand: Extraktionslogik).\n</li><li><em>Activity Final Node</em> (Endknoten, Bullseye-Symbol).\n</li><li><em>Note</em>: Präzisiert Bitposition, Ausrichtung und Platzhaltersemantik.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Synchroner Aufruf als Teilschritt innerhalb von <code>E2E_PXXmSourceCheck()</code> bzw. <code>E2E_PXXmSinkCheck()</code> nach erfolgter Längenvalidierung des Puffers.\n</li><li><strong>Datenextraktion &amp; Bit-Transformation:</strong>\n<ul class=\"fig-list\"><li><strong>Zieladresse:</strong> Zugriff auf das Byte an der Position <code>Offset + PXXMMESSAGE_POS</code> im Puffer <code>Data</code>.\n</li><li><strong>Bit-Extraktion:</strong> Adressiert sind die beiden höchstwertigen Bits (<em>Most Significant Bits</em>, Bits 7 und 6 des adressierten Bytes).\n</li><li><strong>Normalisierung / Alignment:</strong> Die 2 Bits werden extrahiert und in die niederwertigsten Bits (<em>Least Significant Bits</em>, Bits 1 und 0) der Variablen <code>ReceivedMessageType</code> verschoben:\n $$\\text{ReceivedMessageType} = (\\text{Data}[\\text{Offset} + \\text{PXXMMESSAGE\\_POS}] \\gg 6) \\ \\&amp; \\ 0\\text{x}03$$\n</li></ul>\n</li><li><strong>Abschluss:</strong> Verlassen der Sequenz über den <em>Activity Final Node</em>; <code>ReceivedMessageType</code> steht unmittelbar für den anschließenden Abgleich gegen den erwarteten Typ (Request / Response / Error) und die Zustandsbewertung der E2E-State-Machine zur Verfügung.\n</li><li><strong>Fehlerpfade / Callbacks:</strong> Der Teilschritt führt keine Det-/Dem-Meldungen aus. Ungültige oder inkonsistente Nachrichtentypen führen in den nachgelagerten Entscheidungsknoten der Check-Routine zur Einstufung als fehlerhafte Nachricht (<code>E2E_E_WRONGSTATUS</code> o. ä.).\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Exakte Bit-Ausrichtung:</strong> Zwingende Rechtsverschiebung auf die LSBs. Eine fehlerhafte Bitmaskierung oder Nichtbeachtung des MSB-zu-LSB-Transfers führt zur Fehlinterpretation des Nachrichtentyps und zur Verwerfung gültiger Requests/Responses.\n</li><li><strong>Pufferschutz (Out-of-Bounds-Prevention):</strong> Vor Ausführung dieses Schritts muss in der Check-Funktion garantiert sein, dass die PDU-Länge mindestens <code>Offset + PXXMMESSAGE_POS + 1</code> Byte umfasst.\n</li><li><strong>Integrationsort:</strong> Relevanter API-Vertrag für Entwickler von E2E-Bibliotheken (<code>E2E</code>), E2E-Transformern (<code>E2EXf</code> im Classic AUTOSAR) sowie adaptiven Kommunikations-Stacks (<code>ara::com</code> E2E-Handler).\n</li></ul>"}, {"id": "FIG-b1a58afe908b1a6b", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (Activity Diagram).\n</li><li><strong>Architektur-Kontext &amp; Zweck:</strong>\n<ul class=\"fig-list\"><li>Spezifikationskontext: AUTOSAR Foundation E2E Protocol Specification ([PRS_E2E_01191], bezogen auf [RS_E2E_08539], Releases R22-11 / R23-11).\n</li><li>Funktionaler Bereich: E2E-Methodenprofile (<code>PXXm</code>, z. B. P04m, P07m, P22m) zur E2E-Absicherung serviceorientierter Client/Server- und Request/Response-Kommunikation (z. B. via SOME/IP über den E2E Transformer bzw. ara::com / RTE).\n</li><li>Zweck: Normative Definition des atomaren Dekodierungsschritts <em>„Read Message Type“</em> innerhalb der Empfänger-Prüfroutinen <code>E2E_PXXmSourceCheck()</code> (Client-seitig zur Response-Prüfung) und <code>E2E_PXXmSinkCheck()</code> (Server-seitig zur Request-Prüfung).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivitätskontexte:</strong>\n<ul class=\"fig-list\"><li><code>E2E_PXXmSourceCheck()</code>: Prüfroutine der Quelle (Client/Caller-Perspektive).\n</li><li><code>E2E_PXXmSinkCheck()</code>: Prüfroutine der Senke (Server/Callee-Perspektive).\n</li><li>Platzhalter <code>XX</code>: Kennzeichnet das konkrete Basisprofil (z. B. 04, 07); <code>m</code> kennzeichnet die Methoden-Profilvariante.\n</li></ul>\n</li><li><strong>Eingangsdaten &amp; Variablen:</strong>\n<ul class=\"fig-list\"><li><code>Data</code>: Bytestring-Puffer (<code>const uint8*</code>) der empfangenen serialisierten PDU/Payload.\n</li><li><code>ReceivedMessageType</code>: Lokale Variable (Typ <code>uint8</code> bzw. profil-spezifisches Enum) zur Speicherung des normalisierten 2-Bit-Nachrichtentyps.\n</li><li><code>Offset</code>: Konfigurierter Basis-Offset (in Byte/Bit je nach Profilspezifikation) des E2E-Headers innerhalb der PDU.\n</li><li><code>PXXMMESSAGE_POS</code>: Profilspezifische Konstante für die relative Position des Message-Type-Felds.\n</li></ul>\n</li><li><strong>UML-Notationselemente:</strong>\n<ul class=\"fig-list\"><li><em>Initial Node</em> (Startknoten, gefüllter schwarzer Kreis).\n</li><li><em>Opaque Action</em> (Aktionszustand: Extraktionslogik).\n</li><li><em>Activity Final Node</em> (Endknoten, Bullseye-Symbol).\n</li><li><em>Note</em>: Präzisiert Bitposition, Ausrichtung und Platzhaltersemantik.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Synchroner Aufruf als Teilschritt innerhalb von <code>E2E_PXXmSourceCheck()</code> bzw. <code>E2E_PXXmSinkCheck()</code> nach erfolgter Längenvalidierung des Puffers.\n</li><li><strong>Datenextraktion &amp; Bit-Transformation:</strong>\n<ul class=\"fig-list\"><li><strong>Zieladresse:</strong> Zugriff auf das Byte an der Position <code>Offset + PXXMMESSAGE_POS</code> im Puffer <code>Data</code>.\n</li><li><strong>Bit-Extraktion:</strong> Adressiert sind die beiden höchstwertigen Bits (<em>Most Significant Bits</em>, Bits 7 und 6 des adressierten Bytes).\n</li><li><strong>Normalisierung / Alignment:</strong> Die 2 Bits werden extrahiert und in die niederwertigsten Bits (<em>Least Significant Bits</em>, Bits 1 und 0) der Variablen <code>ReceivedMessageType</code> verschoben:\n $$\\text{ReceivedMessageType} = (\\text{Data}[\\text{Offset} + \\text{PXXMMESSAGE\\_POS}] \\gg 6) \\ \\&amp; \\ 0\\text{x}03$$\n</li></ul>\n</li><li><strong>Abschluss:</strong> Verlassen der Sequenz über den <em>Activity Final Node</em>; <code>ReceivedMessageType</code> steht unmittelbar für den anschließenden Abgleich gegen den erwarteten Typ (Request / Response / Error) und die Zustandsbewertung der E2E-State-Machine zur Verfügung.\n</li><li><strong>Fehlerpfade / Callbacks:</strong> Der Teilschritt führt keine Det-/Dem-Meldungen aus. Ungültige oder inkonsistente Nachrichtentypen führen in den nachgelagerten Entscheidungsknoten der Check-Routine zur Einstufung als fehlerhafte Nachricht (<code>E2E_E_WRONGSTATUS</code> o. ä.).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Exakte Bit-Ausrichtung:</strong> Zwingende Rechtsverschiebung auf die LSBs. Eine fehlerhafte Bitmaskierung oder Nichtbeachtung des MSB-zu-LSB-Transfers führt zur Fehlinterpretation des Nachrichtentyps und zur Verwerfung gültiger Requests/Responses.\n</li><li><strong>Pufferschutz (Out-of-Bounds-Prevention):</strong> Vor Ausführung dieses Schritts muss in der Check-Funktion garantiert sein, dass die PDU-Länge mindestens <code>Offset + PXXMMESSAGE_POS + 1</code> Byte umfasst.\n</li><li><strong>Integrationsort:</strong> Relevanter API-Vertrag für Entwickler von E2E-Bibliotheken (<code>E2E</code>), E2E-Transformern (<code>E2EXf</code> im Classic AUTOSAR) sowie adaptiven Kommunikations-Stacks (<code>ara::com</code> E2E-Handler).\n</li></ul>"}], "trans": [{"from": "FIG-6f81e1b0fd2139ab", "to": "FIG-b1a58afe908b1a6b", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Knoten <code>E2E_PXXmSinkCheck</code>:</strong> Der Methodenname und die Klammern <code>()</code> sind nun auf zwei Zeilen aufgeteilt (<code>E2E_PXXmSinkCheck</code> oben, <code>()</code> darunter zentriert), analog zur Darstellung in <code>E2E_PXXmSourceCheck</code>.\n</li><li><strong>Kopfbereich:</strong> Artefakt-Textreste oberhalb des Diagramms („...meSinkCheck() shall behave as shown in Figure 6.44...“) wurden im Zuschnitt entfernt.\n</li></ul>"}]};
